let data = msg.payload;

if (Buffer.isBuffer(data)) {
    data = data.toString('utf8');
}

if (typeof data === 'string') {
    try {
        data = JSON.parse(data);
    } catch (e) {
        node.error("Failed to parse JSON. Ensure the file is valid JSON.", msg);
        return null;
    }
}

// 1. Validate the new JSON structure
if (!data || typeof data !== 'object' || Array.isArray(data) || !Array.isArray(data.places) || !Array.isArray(data.edges)) {
    node.error("Expected the JSON to be an object containing 'places' and 'edges' arrays.", msg);
    return null;
}

const queryParts = [];

// 2. Generate Nodes dynamically from data.places
queryParts.push(" // Creazione dei nodi");
data.places.forEach(place => {
    if (place.id) {
        const properties = [];

        // Aggiungi le proprietà base
        properties.push(`id: '${place.id}'`);
        if (place.name) {
            properties.push(`name: '${place.name}'`);
        }

        // Aggiungi gli attributi dinamicamente (ignorando i valori null)
        if (place.attributes) {
            for (const key in place.attributes) {
                const value = place.attributes[key];
                if (value !== null && value !== undefined) {
                    if (typeof value === 'string') {
                        properties.push(`${key}: '${value}'`);
                    } else {
                        properties.push(`${key}: ${value}`);
                    }
                }
            }
        }

        // Gestione opzionale delle coordinate (salvate come stringa JSON)
        if (place.coordinates && place.coordinates.length > 0) {
             properties.push(`coordinates: '${JSON.stringify(place.coordinates)}'`);
        }

        const propsString = properties.join(', ');
        queryParts.push(` (${place.id}:Place {${propsString}})`);
    }
});

// 3. Generate Relationships from data.edges
// 3. Generate Relationships from data.edges
queryParts.push("\n // Creazione delle relazioni");
data.edges.forEach(edge => {
    if (edge.source && edge.target) {
        // Estrai il tipo di relazione, formattalo in maiuscolo (standard Cypher) o usa un default
        const relType = edge.type ? edge.type.toUpperCase().replace(/\s+/g, '_') : 'CONNECTED_TO';

        // Estrai le proprietà della relazione (se presenti)
        let edgePropsString = "";
        if (edge.attributes && Object.keys(edge.attributes).length > 0) {
            const edgeProps = [];
            for (const key in edge.attributes) {
                const value = edge.attributes[key];
                if (value !== null && value !== undefined) {
                    if (typeof value === 'string') {
                        edgeProps.push(`${key}: '${value}'`);
                    } else {
                        edgeProps.push(`${key}: ${value}`);
                    }
                }
            }
            if (edgeProps.length > 0) {
                edgePropsString = ` {${edgeProps.join(', ')}}`;
            }
        }

        // Genera la stringa Cypher per la relazione con le eventuali proprietà
        queryParts.push(`\n // ${edge.source} -[${relType}]-> ${edge.target}`);
        queryParts.push(` (${edge.source})-[:${relType}${edgePropsString}]->(${edge.target})`);
    }
});

// 4. Build the final query string
let finalQuery = "CREATE\n";

for (let i = 0; i < queryParts.length; i++) {
    const part = queryParts[i];

    let isLastStatement = true;
    for (let j = i + 1; j < queryParts.length; j++) {
        if (!queryParts[j].trim().startsWith("//")) {
            isLastStatement = false;
            break;
        }
    }

    if (part.trim().startsWith("//")) {
        finalQuery += part + "\n";
    } else {
        finalQuery += part;
        if (!isLastStatement) {
            finalQuery += ",\n";
        } else {
            finalQuery += ";\n";
        }
    }
}

msg.query = finalQuery;
return msg;

