const data = msg.payload;
const [department, room] = data.room.split(':');
const isHazard = data.danger_score > 0;

// 1. Parametri ridotti al minimo
msg.params = {
    department, room,
    type: data.danger_type,
    level: data.danger,
    score: data.danger_score,
    warning: data.warning,
    justification: data.justification,

    // k: Costante moltiplicativa per scalare il peso del pericolo.
    // Esempio: se score=0.5 e k=10, il peso della stanza aumenterà di 5 volte.
    k: 10 
};

msg.database = "memgraph";

// 2. Logica Operativa
if (isHazard) {
    // Calcolo semplificato direttamente in Cypher
    msg.query = `
        MATCH (p:Place {department: $department, room: $room})

        MERGE (h:Hazard {type: $type})-[:AFFECTS]->(p)
        SET h += { level: $level, score: $score, warning: $warning, justification: $justification },
            p.dynamic_weight = coalesce(p.weight, 1.0) * (1 + ($score * $k))

        RETURN p, h;
    `;
} else {
    // Ripristino e pulizia se il pericolo è a 0
    msg.query = `
        MATCH (p:Place {department: $department, room: $room})
        OPTIONAL MATCH (h:Hazard {type: $type})-[:AFFECTS]->(p)
        DETACH DELETE h

        SET p.dynamic_weight = coalesce(p.weight, 1.0)

        RETURN p;
    `;
}

