msg.query = `
// 1. Trova sorgente e target
MATCH (source:Place {department: $department, room: $room})
MATCH (target:Place) 
WHERE target.room IN ['E1', 'E2', 'E3', 'E4', 'E5', 'E6', 'E7']

// 2. Calcola i percorsi
MATCH path = (source)-[:CONNECTED_TO *WSHORTEST (edge, node | coalesce(node.dynamic_weight, node.weight)) total_weight]->(target)

// 3. Salva i risultati temporaneamente per non perderli a causa del DELETE
WITH collect({Destination: target.room, path: path, weight: total_weight}) AS all_paths, path

// 4. Estrai i nodi di partenza in modo UNIVOCO per pulirli
UNWIND relationships(path) AS rel
WITH DISTINCT startNode(rel) AS start_node, all_paths

// 5. Pulisci i vecchi archi (eseguito una sola volta per nodo)
OPTIONAL MATCH (start_node)-[old:SHORTEST_PATH]->()
DELETE old

// 6. Ricrea i nuovi archi usando i dati salvati prima
WITH all_paths
UNWIND all_paths AS res
UNWIND relationships(res.path) AS rel
WITH startNode(rel) AS start_node, endNode(rel) AS end_node, res
MERGE (start_node)-[:SHORTEST_PATH]->(end_node)

// 7. Ritorna i risultati
RETURN DISTINCT 
    res.Destination AS Destination, 
    res.path AS path, 
    res.weight AS total_weight;
    `;

