// 2. Definiamo i parametri del modello matematico
// Puoi modificare questi valori in base alla taratura del tuo sistema
const ALPHA = 1.5;       // Sensibilità ai sensori di pericolo (\alpha)
const BETA = 1.0;        // Sensibilità alla congestione (\beta)
const Q = 0;             // Congestione attuale (Q(t)) - impostabile dinamicamente se hai sensori di affollamento
const ETA = 0.8;         // Soglia limite di pericolo (\eta) per il blocco totale
const OMEGA = 999999;    // Penalità estrema (\Omega) per segnalare il "percorso bloccato"

// 3. Prepariamo i parametri da passare a Memgraph
msg.params = {
    department: department,
    room: roomName,
    type: hazardData.danger_type,
    level: hazardData.danger,
    score: hazardData.danger_score, // Questo è il nostro H(t)
    warning: hazardData.warning,
    justification: hazardData.justification,
    alpha: ALPHA,
    beta: BETA,
    q: Q,
    eta: ETA,
    omega: OMEGA
};

msg.database = "memgraph";

// 4. Logica Operativa: Modello di pathfinding dinamico
if (hazardData.danger_score > 0) {
    // MERGE del pericolo e ricalcolo del peso dinamico
    msg.query = `
        MATCH (p:Place {department: $department, room: $room})

        // Aggiungiamo o aggiorniamo il nodo Hazard
        MERGE (h:Hazard {type: $type})-[:AFFECTS]->(p)
        SET h.level = $level,
            h.score = $score,
            h.warning = $warning,
            h.justification = $justification

        // Calcolo dinamico w(t) = tau * [1 + alpha * H + beta * Q] + Penalità
        WITH p, h, 
             coalesce(p.weight, 1.0) AS tau, // \tau_{ij}: peso base (1.0 di default se manca)
             $score AS H          // H_{ij}(t): hazard score

        // Calcoliamo la base moltiplicata e la penalità in base alla soglia eta
        WITH p, h, tau, H,
             tau * (1 + ($alpha * H) + ($beta * $q)) AS calcolo_base,
             CASE WHEN H > $eta THEN $omega ELSE 0 END AS penalita

        // Salviamo il costo dinamico sulla stanza
        SET p.dynamic_weight = calcolo_base + penalita

        RETURN p, h;
    `;
} else {
    // Se il pericolo rientra, eliminiamo l'Hazard e ripristiniamo il peso a quello base
    msg.query = `
        MATCH (p:Place {department: $department, room: $room})
        OPTIONAL MATCH (h:Hazard {type: $type})-[:AFFECTS]->(p)
        DETACH DELETE h

        // Ripristino del dynamic_weight al valore di base tau
        WITH p, coalesce(p.weight, 1.0) AS tau
        SET p.dynamic_weight = tau

        RETURN p;
    `;
}

